package com.example.partnerintegrationmock.integration;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.UUID;
@Component public class AppointmentCallbackClient { private final RestClient client; public AppointmentCallbackClient(RestClient.Builder builder,@Value("${partner-mock.appointment.base-url}") String url){client=builder.baseUrl(url).build();} public void confirm(UUID id,String ref){post("/api/v1/integration/appointments/"+id+"/confirmed",ref);} public void complete(UUID id,String ref){post("/api/v1/integration/appointments/"+id+"/completed",ref);} private void post(String path,String ref){client.post().uri(path).contentType(MediaType.APPLICATION_JSON).body(new CallbackRequest(ref)).retrieve().toBodilessEntity();} record CallbackRequest(String externalDmsReference){} }
